//! Type and function definitions for the GDExtension API.
//!
//! Mostly contains modified versions of code generated by `bindgen` from the
//! `gdextension_interface.h` files in the [`4.0-stable`] and [`4.1-stable`] versions of the Godot
//! tree.
//!
//! [`4.0-stable`]: https://github.com/godotengine/godot/blob/4.0-stable/core/extension/gdextension_interface.h
//! [`4.1-stable`]: https://github.com/godotengine/godot/blob/4.1-stable/core/extension/gdextension_interface.h
//!
//! # Backwards Compatibility
//! In general, the GDExtension API is very backwards compatible, with the API being properly
//! versioned: assuming the editor build has deprecated features enabled - which all official editor
//! builds do - the API from 4.0 still works in the latest build.
//!
//! There are two notable exceptions:
//! - In 4.1, the API was changed from providing a `GDExtensionInterface` structure containing many
//!   function pointers, to a `GDExtensionInterfaceGetProcAddress` that returns a function pointer
//!   for a function by name. This made expanding the API non-breaking.
//! - In 4.2, [b0a33cac][https://github.com/godotengine/godot/commit/b0a33cac7c9c46e80979d1a507305cf71b3f6a40#diff-29b903ebcf0b26a6b2fa3e617462e06b69b6d5201e1dda76095076949da8a0f8R412]
//!   changed the type of a field in `GDExtensionCallableCustomInfo` without making a new version
//!   of the struct.
mod after_v41;
mod string;
mod v40;
mod variant;
mod vector;

pub use self::after_v41::*;
pub use self::string::GDExtensionStringName;
pub use self::v40::*;
pub use self::variant::GDExtensionVariant;
pub use self::vector::PackedArray;

use std::fmt::Debug;

/// Either a [`*const GDExtensionInterface`] or [`GDExtensionInterfaceGetProcAddress`], depending
/// on the Godot version in use.
///
/// [`*const GDExtensionInterface`]: GDExtensionInterface
#[repr(C)]
#[derive(Copy, Clone)]
pub union GDExtensionInterfaceUnknown {
    direct_interface: *const GDExtensionInterface,
    get_proc_address: GDExtensionInterfaceGetProcAddress,
}

const _: () = {
    if size_of::<GDExtensionInterfaceUnknown>() != size_of::<*const ()>() {
        panic!("GDExtensionInterfaceUnknown size is wrong");
    }

    if align_of::<GDExtensionInterfaceUnknown>() != align_of::<*const ()>() {
        panic!("GDExtensionInterfaceUnknown alignment is wrong");
    }
};

impl Debug for GDExtensionInterfaceUnknown {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // SAFETY: Both union variants are pointers.
        write!(f, "GDExtensionInterfaceUnknown({:p})", unsafe {
            self.direct_interface
        })
    }
}

impl GDExtensionInterfaceUnknown {
    /// Gets a [GDExtensionInterface], either by a copy from the provided version or by looking up
    /// each function depending on which Godot version we're using. Note that this operation is
    /// quite expensive so the result should be stored.
    pub unsafe fn resolve(&self) -> GDExtensionInterface {
        // Godot 4.0's interface is a direct pointer to GDExtensionInterface,
        // but 4.1 and onwards use GDExtensionInterfaceGetProcAddress. Since
        // GDExtensionInterface starts with a version number, we can dereference
        // this pointer and check if it equals the major version (4) to determine
        // what engine version we're running on. Yes, this hack is as stupid as it
        // sounds. In theory, GDExtensionInterfaceGetProcAddress could also start
        // with a `4` but it doesn't make sense as an instruction to start a function
        // on any major ISA.

        let maybe_major_version = unsafe { *self.direct_interface.cast::<u32>() };
        let is_4_0 = maybe_major_version == 4;

        if is_4_0 {
            unsafe { *self.direct_interface }
        } else {
            unsafe { GDExtensionInterface::from_get_proc_address(self.get_proc_address) }
        }
    }
}

